    prompt: 'Refer to the exhibit. Which prefix does Router1 use for traffic to Host A?',
    options: [
      { key: 'A', text: '10.10.10.0/28' },
      { key: 'B', text: '10.10.13.0/25' },
      { key: 'C', text: '10.10.13.144/28' },
      { key: 'D', text: '10.10.13.208/29' },
    ],
